	/**
	 * Default Constructor
	 */
    public MerchantService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new MerchantEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(MerchantRepository.class) );
		this.validator		= applicationContext.getBean(MerchantValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Merchant
	 */
		public Merchant createMerchant( CreateMerchantCommand command ) {

		Merchant entity = new Merchant();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setMerchantId( command.getMerchantId() );
            entity.setName( command.getName() );
            entity.setMcc( command.getMcc() );
            entity.setUrl( command.getUrl() );
            entity.setCountry( command.getCountry() );
            entity.setSettlementCurrency( command.getSettlementCurrency() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Merchant {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateMerchantCommand
	 * @return		Merchant
	 */
	public Merchant updateMerchant( UpdateMerchantCommand command ) {

		Merchant entity = new Merchant();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setMerchantId( command.getMerchantId() );
            entity.setName( command.getName() );
            entity.setMcc( command.getMcc() );
            entity.setUrl( command.getUrl() );
            entity.setCountry( command.getCountry() );
            entity.setSettlementCurrency( command.getSettlementCurrency() );
            entity.setTerminals( command.getTerminals() );
            entity.setPaymentContracts( command.getPaymentContracts() );
            entity.setPayouts( command.getPayouts() );
            entity.setSettlements( command.getSettlements() );
            entity.setDisputes( command.getDisputes() );
            entity.setInvoices( command.getInvoices() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Merchant {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteMerchantCommand
	 */
	public void delete( DeleteMerchantCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getMerchantId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Merchant {0} ", id );

	}

	/**
	 * Method to retrieve the Merchant via MerchantFetchOneSummary
	 * @param 	summary MerchantFetchOneSummary
	 * @return 	MerchantFetchOneResponse
	 */
	public Merchant getMerchant( MerchantFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "MerchantFetchOneSummary arg cannot be null" );

		Merchant entity = null;
		UUID id = summary.getMerchantId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Merchant using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Merchants
	 *
	 * @return 	List<Merchant>
	 */
    public List<Merchant> getAllMerchant() {
		List<Merchant> list = projector.findAll( new FindAllMerchantQuery() );
		return list;
	}


